/**
 * Key handoff to Home Assistant, in two halves:
 *
 * 1. Cross-language: `shared/handoff-vectors.json` is generated by the HA
 *    integration's Python reference (scripts/generate_handoff_vector.py there)
 *    with fixed keys and nonce. Matching its envelope byte for byte proves HA
 *    can decrypt what this app sends.
 * 2. Link parsing and its refusals, which have no Python counterpart.
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

import { fromHex, toBase64Url, toHex, utf8 } from '../src/bytes.js';
import { decodeBundle } from '../src/bundle.js';
import {
  HandoffError,
  encryptHandoff,
  handoffDeliveryUrl,
  isPrivateHost,
  parseHandoffLink,
} from '../src/handoff.js';

interface HandoffVector {
  qr_link: string;
  ha_url: string;
  token: string;
  address: string;
  ha_public: string;
  client_private_scalar: string;
  client_public: string;
  nonce: string;
  plaintext: string;
  envelope: string;
  delivery_url: string;
}

const vectorPath = fileURLToPath(new URL('../../../../shared/handoff-vectors.json', import.meta.url));
const vector: HandoffVector = JSON.parse(readFileSync(vectorPath, 'utf8'));

/** WebCrypto imports an EC private key from JWK only, which needs the public
 * point alongside the scalar. */
async function importClientKeyPair(scalarHex: string, publicHex: string): Promise<CryptoKeyPair> {
  const point = fromHex(publicHex);
  const jwk = {
    kty: 'EC',
    crv: 'P-256',
    x: toBase64Url(point.subarray(1, 33)),
    y: toBase64Url(point.subarray(33, 65)),
  };
  const algorithm = { name: 'ECDH', namedCurve: 'P-256' };
  return {
    privateKey: await crypto.subtle.importKey(
      'jwk',
      { ...jwk, d: toBase64Url(fromHex(scalarHex)) },
      algorithm,
      false,
      ['deriveBits'],
    ),
    publicKey: await crypto.subtle.importKey('jwk', jwk, algorithm, true, []),
  };
}

function link(payload: Record<string, unknown>): string {
  return (
    'https://the78mole.github.io/hoermoles-ble/app/#ha=' + toBase64Url(utf8(JSON.stringify(payload)))
  );
}

const VALID = {
  v: 1,
  u: vector.ha_url,
  k: toBase64Url(fromHex(vector.ha_public)),
  a: 'f1:26:af:cc:41:86',
  n: 'Home',
};

describe('the Python reference vector', () => {
  it('parses the QR link HA generates', () => {
    const request = parseHandoffLink(vector.qr_link);
    expect(request).not.toBeNull();
    expect(request!.url).toBe(vector.ha_url);
    expect(request!.token).toBe(vector.token);
    expect(toHex(request!.publicKey)).toBe(vector.ha_public);
    expect(request!.address).toBe(vector.address);
    expect(request!.name).toBe('Home');
    expect(request!.host).toBe('192.168.1.10:8123');
    expect(request!.secure).toBe(false);
    expect(request!.privateHost).toBe(true);
  });

  it('produces the same envelope and delivery URL byte for byte', async () => {
    const request = parseHandoffLink(vector.qr_link)!;
    const envelope = await encryptHandoff(request, vector.plaintext, {
      clientKeyPair: await importClientKeyPair(vector.client_private_scalar, vector.client_public),
      nonce: fromHex(vector.nonce),
    });
    expect(toHex(envelope)).toBe(vector.envelope);
    expect(handoffDeliveryUrl(request, envelope)).toBe(vector.delivery_url);
  });

  it('carries a bundle this app can read', async () => {
    const [entry] = await decodeBundle(vector.plaintext);
    expect(entry.deviceAddress).toBe(vector.address);
  });
});

describe('encryptHandoff', () => {
  it('uses a fresh client key and nonce every time', async () => {
    const request = parseHandoffLink(vector.qr_link)!;
    const first = await encryptHandoff(request, vector.plaintext);
    const second = await encryptHandoff(request, vector.plaintext);
    expect(toHex(first.subarray(0, 4))).toBe(toHex(utf8('HM1H')));
    expect(first.length).toBe(4 + 65 + 12 + utf8(vector.plaintext).length + 16);
    expect(toHex(first)).not.toBe(toHex(second));
  });
});

describe('parseHandoffLink', () => {
  it('returns null for anything that is not a handoff link', () => {
    expect(parseHandoffLink('HMOLES1:abc')).toBeNull();
    expect(parseHandoffLink('https://example.org/#import=HMOLES1:abc')).toBeNull();
  });

  it('accepts the bare fragment and upper-cases the address', () => {
    const request = parseHandoffLink(link(VALID).slice(link(VALID).indexOf('#')));
    expect(request!.address).toBe('F1:26:AF:CC:41:86');
  });

  it('defaults a missing name to empty', () => {
    expect(parseHandoffLink(link({ ...VALID, n: 42 }))!.name).toBe('');
  });

  it.each([
    ['damaged base64/JSON', '#ha=%%%'],
    ['not an object', '#ha=' + toBase64Url(utf8('null'))],
    ['an unknown version', link({ ...VALID, v: 2 })],
    ['no URL', link({ ...VALID, u: 'not a url' })],
    ['a non-HTTP scheme', link({ ...VALID, u: 'javascript:alert(1)' })],
    ['a foreign path', link({ ...VALID, u: 'http://192.168.1.10:8123/steal' })],
    ['a short token', link({ ...VALID, u: 'http://192.168.1.10:8123/api/hoermoles_ble/handoff/abc' })],
    ['a query string', link({ ...VALID, u: vector.ha_url + '?x=1' })],
    ['credentials in the URL', link({ ...VALID, u: vector.ha_url.replace('http://', 'http://u:p@') })],
    ['an invalid key', link({ ...VALID, k: '***' })],
    ['a compressed key', link({ ...VALID, k: toBase64Url(new Uint8Array(33).fill(2)) })],
    ['no drive', link({ ...VALID, a: undefined })],
    ['a malformed drive', link({ ...VALID, a: 'F1:26:AF' })],
  ])('rejects %s', (_label, text) => {
    expect(() => parseHandoffLink(text)).toThrow(HandoffError);
  });

  it('flags public and HTTPS targets', () => {
    const url = 'https://ha.example.org/api/hoermoles_ble/handoff/' + vector.token;
    const request = parseHandoffLink(link({ ...VALID, u: url }))!;
    expect(request.secure).toBe(true);
    expect(request.privateHost).toBe(false);
  });
});

describe('isPrivateHost', () => {
  it.each([
    'localhost',
    'homeassistant.local',
    'ha.home.arpa',
    'nas.lan',
    'ha.internal',
    '10.0.0.5',
    '127.0.0.1',
    '172.16.0.1',
    '172.31.255.1',
    '192.168.178.20',
    '169.254.1.1',
    '100.101.102.103',
    '[::1]',
    '[fd12:3456::1]',
    '[fe80::1]',
  ])('%s is private', (host) => {
    expect(isPrivateHost(host)).toBe(true);
  });

  it.each(['example.org', '8.8.8.8', '172.32.0.1', '192.169.0.1', '100.128.0.1', '[2001:db8::1]'])(
    '%s is public',
    (host) => {
      expect(isPrivateHost(host)).toBe(false);
    },
  );
});
